  function renderSiteHome(siteId, uiOverrides) {
    const site = SITE_BY_ID.get(siteId);
    if (!site || siteId === "workbench") return renderNotFound("这个站点不存在。", "#/workbench");
    const query = uiOverrides && uiOverrides.siteQueries ? uiOverrides.siteQueries[siteId] || "" : ui.siteQueries[siteId] || "";
    const result = Core.searchRecords(siteId, query);
    const noResult = (result.kind === "miss" || result.kind === "multi" || result.kind === "invalid") && result.count === 0
      ? `<div class="site-empty"><h2>没有匹配记录</h2><p>${escapeHtml(result.message || "换一个已读页上的汉字词。")}</p></div>`
      : result.kind === "empty"
        ? `<div class="site-empty"><p>${escapeHtml(result.message)}</p></div>`
        : result.kind === "forbidden"
          ? `<div class="site-empty"><h2>此文件已被禁止访问</h2><p>${escapeHtml(result.message)}</p></div>`
          : "";
    if (siteId === "forum") return renderForumHome(site, query, result, noResult);
    if (siteId === "archive") return renderArchiveHome(site, query, result, noResult);
    if (siteId === "folk") return renderFolkHome(site, query, result, noResult);
    if (siteId === "news") return renderNewsHome(site, query, result, noResult);
    return renderGeologyHome(site, query, result, noResult);
  }

